            'string.empty': 'Enter your full name',
            'any.required': 'Enter your full name'
          }),
          'dob-day': Joi.number().integer().min(1).max(31).required().messages({
            'number.base': 'Enter a day',
            'number.min': 'Day must be between 1 and 31',
            'number.max': 'Day must be between 1 and 31',
            'any.required': 'Enter a day'
          }),
          'dob-month': Joi.number().integer().min(1).max(12).required().messages({
            'number.base': 'Enter a month',
            'number.min': 'Month must be between 1 and 12',
            'number.max': 'Month must be between 1 and 12',
            'any.required': 'Enter a month'
          }),
          'dob-year': Joi.number().integer().min(1900).max(new Date().getFullYear()).required().messages({
            'number.base': 'Enter a year',
            'number.min': 'Enter a valid year',
            'number.max': 'Enter a valid year',
            'any.required': 'Enter a year'
          }),
          crumb: Joi.string()
        }),
        failAction: (_request, h, error) => {
          const errors = error.details.map((detail) => ({
            text: detail.message,
            href: `#${detail.context.key}`
          }))
          return h.view('registration/name', {
            pageTitle: 'Error: What is your full name?',
            errorSummary: errors,
            errors: Object.fromEntries(
              error.details.map((d) => [d.context.key, { text: d.message }])
            )
          }).takeover()
        }
      }
    },
    handler: (_request, h) => {
      return h.redirect('/register/email')
    }
  }
]

